package android.content;import android.net.Uri;import android.os.Bundle;public class ContentResolver {public boolean active,unavailable,missing,bridgeKnown,bridgeConnected,bridgeShared;public Bundle call(Uri uri,String method,String arg,Bundle extras){if(unavailable)throw new IllegalStateException();if(missing)return null;Bundle b=new Bundle();b.putBoolean("active",active);if(bridgeKnown){b.putBoolean("connected",bridgeConnected);b.putBoolean("shared",bridgeShared);}return b;}}
